"""ETEC Nafes National Assessment — English Grade 3 (CEFR A1 Primary Literacy & Language) Question Bank: 360 Verified MCQs."""
try:
    from nafes_ext_common import (
        make_english_q,
        svg_idea_map,
        svg_reading_card,
        svg_sequence_strip,
        svg_tense_timeline,
        svg_word_morphology,
        wrap_passage_box,
    )
except ImportError:
    from scripts.nafes_ext_common import (
        make_english_q,
        svg_idea_map,
        svg_reading_card,
        svg_sequence_strip,
        svg_tense_timeline,
        svg_word_morphology,
        wrap_passage_box,
    )

LEVEL = "English · Grade 3"


def _diff(idx: int) -> str:
    if idx < 5:
        return "Easy"
    if idx < 10:
        return "Medium"
    return "Hard"


def _emit_bp(items: list[dict], bp_num: int, topic: str, specs: list[dict]) -> None:
    assert len(specs) == 15, f"Blueprint B{bp_num:02d} expected 15 items, got {len(specs)}"
    bp = f"G3-ENG-B{bp_num:02d}"
    for idx, sp in enumerate(specs):
        qid = f"NAFS-ENG-G3-{len(items) + 1:03d}"
        box = wrap_passage_box(sp["passage"]) if sp.get("passage") else ""
        q_en = f'{sp["lead_en"]}{box}{sp.get("ask_en", "")}'
        q_ar = f'{sp["lead_ar"]}{box}{sp.get("ask_ar", "")}'
        items.append(
            make_english_q(
                qid=qid,
                level=LEVEL,
                topic=topic,
                difficulty=_diff(idx),
                blueprint=bp,
                q_en=q_en,
                q_ar=q_ar,
                options=sp["options"],
                hint_en=sp["hint_en"],
                hint_ar=sp["hint_ar"],
                idea_en=sp["idea_en"],
                steps_en=sp["steps_en"],
                check_en=sp["check_en"],
                idea_ar=sp["idea_ar"],
                steps_ar=sp["steps_ar"],
                check_ar=sp["check_ar"],
                diagram_en=sp.get("diagram"),
            )
        )


def _q(
    lead_en: str,
    lead_ar: str,
    passage: str,
    ask_en: str,
    ask_ar: str,
    options: list[str],
    hint_en: str,
    hint_ar: str,
    idea_en: str,
    steps_en: list[str],
    check_en: str,
    idea_ar: str,
    steps_ar: list[str],
    check_ar: str,
    diagram: str = None,
) -> dict:
    return {
        "lead_en": lead_en,
        "lead_ar": lead_ar,
        "passage": passage,
        "ask_en": ask_en,
        "ask_ar": ask_ar,
        "options": options,
        "hint_en": hint_en,
        "hint_ar": hint_ar,
        "idea_en": idea_en,
        "steps_en": steps_en,
        "check_en": check_en,
        "idea_ar": idea_ar,
        "steps_ar": steps_ar,
        "check_ar": check_ar,
        "diagram": diagram,
    }


