            "Look for a detail anyone can observe and check—not words like 'best' or 'prettier'.",
            "ابحث عن معلومة يمكن التحقق منها، لا كلمات رأي مثل best أو prettier.",
            "A fact can be verified by observation; opinions express personal preference.",
