def build_g3_english_bank() -> list[dict]:
    """Build all 360 verified Grade 3 ETEC Nafes English MCQs (24 blueprints x 15 variants)."""
    items: list[dict] = []

    rc = "Reading Comprehension"
    ta = "Text Analysis & Purpose"
    vc = "Vocabulary & Context Clues"
    gr = "Grammar & Sentence Structure"

    for bp_num, fn in enumerate((_b01_specs, _b02_specs, _b03_specs, _b04_specs, _b05_specs, _b06_specs), start=1):
        _emit_bp(items, bp_num, rc, fn())
    for bp_num, fn in enumerate((_b07_specs, _b08_specs, _b09_specs, _b10_specs, _b11_specs, _b12_specs), start=7):
        _emit_bp(items, bp_num, ta, fn())
    for bp_num, fn in enumerate((_b13_specs, _b14_specs, _b15_specs, _b16_specs, _b17_specs, _b18_specs), start=13):
        _emit_bp(items, bp_num, vc, fn())
    for bp_num, fn in enumerate((_b19_specs, _b20_specs, _b21_specs, _b22_specs, _b23_specs, _b24_specs), start=19):
        _emit_bp(items, bp_num, gr, fn())

    assert len(items) == 360, f"Expected 360 Grade 3 English items, got {len(items)}"
    return items
